using System.Buffers.Binary;
using System.Security.Cryptography;
using System.Text;
using Bogus;

namespace Preview.DataSeeder;

/// <summary>
/// Turns a copy of real data into data that keeps its shape but identifies nobody.
/// <list type="bullet">
/// <item>Identifiers: HMAC-SHA256 with a secret salt. Stable (references stay consistent), not reversible without the salt.</item>
/// <item>Names and emails: generated by Bogus from a seed derived from the pseudonymous id, so the same person always gets the same fake identity.</item>
/// <item>Dates: shifted by a per-person offset of up to ±45 days; durations and ordering are preserved, real dates are not.</item>
/// <item>Free text (comments, rejection reasons): replaced, because people write anything in it.</item>
/// </list>
/// </summary>
internal sealed class Pseudonymizer
{
    private const int MaxShiftDays = 45;

    private readonly byte[] _salt;

    public Pseudonymizer(byte[] salt)
    {
        ArgumentNullException.ThrowIfNull(salt);
        if (salt.Length < 32)
        {
            throw new ArgumentException("The salt must be at least 256 bits.", nameof(salt));
        }

        _salt = salt;
    }

    public Dataset Pseudonymize(Dataset source)
    {
        ArgumentNullException.ThrowIfNull(source);

        var shifts = source.Employees.ToDictionary(e => e.Id, e => ShiftDays(e.Id));
        var employees = source.Employees.Select(e =>
        {
            var id = Id(e.Id);
            var (name, email) = Identity(id);
            return new EmployeeRow(id, name, email, e.ManagerId is { } manager ? Id(manager) : null);
        }).ToList();

        var requests = source.AbsenceRequests.Select(r =>
        {
            var shift = shifts.GetValueOrDefault(r.EmployeeId);
            return r with
            {
                Id = Id(r.Id),
                EmployeeId = Id(r.EmployeeId),
                StartDate = r.StartDate.AddDays(shift),
                EndDate = r.EndDate.AddDays(shift),
                SubmittedAt = r.SubmittedAt.AddDays(shift),
                DecidedAt = r.DecidedAt?.AddDays(shift),
                DecidedBy = r.DecidedBy is { } decider ? Id(decider) : null,
                Comment = r.Comment is null ? null : "Comment removed during pseudonymisation.",
                RejectionReason = r.RejectionReason is null ? null : "Reason removed during pseudonymisation.",
            };
        }).ToList();

        return new Dataset(employees, requests);
    }

    internal Guid Id(Guid original)
    {
        var hash = HMACSHA256.HashData(_salt, original.ToByteArray());
        return new Guid(hash.AsSpan(0, 16));
    }

    internal int ShiftDays(Guid original)
    {
        var hash = HMACSHA256.HashData(_salt, Encoding.UTF8.GetBytes("shift:" + original));
        var value = BinaryPrimitives.ReadUInt32LittleEndian(hash);
        return (int)(value % ((MaxShiftDays * 2) + 1)) - MaxShiftDays;
    }

    private static (string Name, string Email) Identity(Guid pseudonymousId)
    {
        var faker = new Faker("fr") { Random = new Randomizer(BitConverter.ToInt32(pseudonymousId.ToByteArray(), 0)) };
        var first = faker.Name.FirstName();
        var last = faker.Name.LastName();
        // example.invalid can never route mail (RFC 2606): a leaked preview cannot email anyone.
        var email = $"{faker.Internet.UserName(first, last).ToLowerInvariant()}.{pseudonymousId.ToString("N")[..6]}@example.invalid";
        return ($"{first} {last}", email);
    }
}
